function dagParse(text){
  var dur={}, edges=[], nodes=[], seen={};
  function add(x){ if(!seen[x]){ seen[x]=1; nodes.push(x); if(!(x in dur)) dur[x]=1; } }
  var lines=String(text||'').split('\n');
  for(var i=0;i<lines.length;i++){
    var ln=lines[i].trim();
    if(!ln || ln.charAt(0)==='#') continue;
    var me=/^(.+?)\s*->\s*(.+)$/.exec(ln);
    if(me){ var a=me[1].trim(), b=me[2].trim();
      if(!a||!b) return { error:'第 '+(i+1)+' 行节点为空' };
      add(a); add(b); edges.push([a,b]); continue; }
    var md=/^(.+?)\s*=\s*([\d.]+)$/.exec(ln);
    if(md){ var t=Number(md[2]);
      if(!isFinite(t)||t<0) return { error:'第 '+(i+1)+' 行工期非法' };
      dur[md[1].trim()]=t; add(md[1].trim()); continue; }
    return { error:'第 '+(i+1)+' 行格式错误（A=3 或 A -> B）' };
  }
  return { error:null, nodes:nodes, edges:edges, dur:dur };
}
function dagTopo(g){
  var indeg={}, adj={}, i;
  for(i=0;i<g.nodes.length;i++){ indeg[g.nodes[i]]=0; adj[g.nodes[i]]=[]; }
  for(i=0;i<g.edges.length;i++){ adj[g.edges[i][0]].push(g.edges[i][1]); indeg[g.edges[i][1]]++; }
  var q=[], order=[];
  for(i=0;i<g.nodes.length;i++) if(indeg[g.nodes[i]]===0) q.push(g.nodes[i]);
  q.sort();
  while(q.length){
    var u=q.shift(); order.push(u);
    var ready=[];
    for(i=0;i<adj[u].length;i++){ var v=adj[u][i]; if(--indeg[v]===0) ready.push(v); }
    ready.sort(); q=q.concat(ready); q.sort();
  }
  if(order.length!==g.nodes.length) return { error:'检测到环，非法 DAG', order:[] };
  return { error:null, order:order };
}
function dagCritical(g){
  var t=dagTopo(g);
  if(t.error) return { error:t.error };
  var finish={}, prev={}, i, j;
  var adjIn={}; for(i=0;i<g.nodes.length;i++) adjIn[g.nodes[i]]=[];
  for(i=0;i<g.edges.length;i++) adjIn[g.edges[i][1]].push(g.edges[i][0]);
  for(i=0;i<t.order.length;i++){
    var u=t.order[i], best=0, bp=null, ins=adjIn[u];
    for(j=0;j<ins.length;j++) if(finish[ins[j]]>best){ best=finish[ins[j]]; bp=ins[j]; }
    finish[u]=best+g.dur[u]; prev[u]=bp;
  }
  var end=null, total=0;
  for(i=0;i<g.nodes.length;i++) if(finish[g.nodes[i]]>total){ total=finish[g.nodes[i]]; end=g.nodes[i]; }
  var path=[]; var cur=end;
  while(cur!==null && cur!==undefined){ path.unshift(cur); cur=prev[cur]; }
  return { error:null, total:total, path:path, finish:finish };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { dagParse:dagParse, dagTopo:dagTopo, dagCritical:dagCritical };
}
if (typeof window !== 'undefined') {
  window.DagForgePure = { dagParse:dagParse, dagTopo:dagTopo, dagCritical:dagCritical };
}
